    std.crypto.random.bytes(std.mem.asBytes(&key));
    const c = k.Cipher.init(key);
    var initial: [16384]B align(16) = undefined;
    std.crypto.random.bytes(std.mem.sliceAsBytes(&initial));
    inline for (.{ false, true }) |inverse| inline for (.{ 64, 1024, 16384 }) |width| try compare(inverse, width, 5, c, &initial);
}

