    var state = input;
    for (0..16) |_| {
        var f: u8 = 0;
        if (inv) {
            f = state[0];
            for (0..15) |i| {
                state[i] = state[i + 1];
                f ^= kuzMul(state[i], coefficients[i]);
            }
            state[15] = f;
        } else {
            for (0..16) |i| f ^= kuzMul(state[i], coefficients[i]);
            var j: usize = 15;
            while (j > 0) : (j -= 1) state[j] = state[j - 1];
            state[0] = f;
        }
    }
    return state;
}
