import json, functools
from pathlib import Path
from derive import mul, COEFF, lin, sumgf
D=json.loads(Path(__file__).with_name('derived.json').read_text())
A,H=D['A'],D['H']
class DAG:
 def __init__(self):
  self.nodes=[('zero',)]+[('input',i)for i in range(16)];self.cache={n:i for i,n in enumerate(self.nodes)}
 def node(self,t):
  if t not in self.cache:self.cache[t]=len(self.nodes);self.nodes.append(t)
  return self.cache[t]
 def xor(self,*args):
  terms=set()
  for a in args:
   if a==0:continue
   if a in terms:terms.remove(a)
   else:terms.add(a)
  if not terms:return 0
  if len(terms)==1:return next(iter(terms))
  return self.node(('xor',)+tuple(sorted(terms)))
 def prod(self,a,c):
  if not a or c==0:return 0
  if c==1:return a
  if self.nodes[a][0]=='mul':
   a,c1=self.nodes[a][1:];c=mul(c,c1)
   return self.prod(a,c)
  return self.node(('mul',a,c))
 def kconv(self,x,c):
  n=len(x);assert len(c)==n and not n&(n-1)
  if n==1:return [self.prod(x[0],c[0])]
  m=n//2
  z0=self.kconv(x[:m],c[:m]);z2=self.kconv(x[m:],c[m:]);z1=self.kconv([self.xor(a,b)for a,b in zip(x[:m],x[m:])],[a^b for a,b in zip(c[:m],c[m:])]);
  z1=[self.xor(a,b,c)for a,b,c in zip(z1,z0,z2)]
  out=[0]*(2*n-1)
  for off,z in[(0,z0),(m,z1),(n,z2)]:
   for i,v in enumerate(z):out[off+i]=self.xor(out[off+i],v)
  return out
 def directconv(self,x,c):
  n=len(x)
  return [self.xor(*(self.prod(x[k],c[i-k])for k in range(i+1)))for i in range(n)]
 def groupedconv(self,x,c):
  n=len(x);out=[]
  for i in range(n):
   groups={}
   for k in range(i+1):groups.setdefault(c[i-k],[]).append(x[k])
   out.append(self.xor(*(self.prod(self.xor(*terms),coeff)for coeff,terms in groups.items())))
  return out
 def reachable(self,outs):
  seen=set()
  def visit(i):
   if i in seen:return
   seen.add(i);t=self.nodes[i]
   for j in (t[1:]if t[0]=='xor'else t[1:2]if t[0]=='mul'else[]):visit(j)
  for i in outs:visit(i)
  return seen
 def stats(self,outs):
  seen=self.reachable(outs);cost=0;counts={t:sum(self.nodes[i][0]==t for i in seen)for t in['mul','xor','input']}
  # XORs of up to three terms can be a single ternlog; larger nodes use balanced ternary trees.
  xorinst=sum((len(self.nodes[i])-2+1)//2 for i in seen if self.nodes[i][0]=='xor')
  @functools.lru_cache(None)
  def depth(i):
   t=self.nodes[i]
   if t[0]in('zero','input'):return (0,0)
   if t[0]=='mul':a,b=depth(t[1]);return a+3,b+1
   ds=sorted([depth(j)[0]for j in t[1:]])
   while len(ds)>1:
    add=ds[:3];ds=ds[3:]+[max(add)+1];ds.sort()
   return ds[0],max(depth(j)[1]for j in t[1:])
  maxdepth=max(depth(i)[0]for i in outs);muldepth=max(depth(i)[1]for i in outs)
  # Liveness in creation/topological order, freeing at last use; not an optimal schedule.
  used={i:0 for i in seen}
  for i in seen:
   t=self.nodes[i]
   for j in (t[1:]if t[0]=='xor'else t[1:2]if t[0]=='mul'else[]):used[j]+=1
  for i in outs:used[i]+=1
  live=set();peak=0
  for i in sorted(seen):
   if self.nodes[i][0]=='zero':continue
   live.add(i);peak=max(peak,len(live))
   t=self.nodes[i]
   for j in (t[1:]if t[0]=='xor'else t[1:2]if t[0]=='mul'else[]):
    used[j]-=1
    if used[j]==0:live.discard(j)
  return dict(gfni=counts['mul'],xor_instructions=xorinst,dag_xor_nodes=counts['xor'],modeled_latency_cycles=maxdepth,multiply_depth=muldepth,creation_order_peak_vectors=peak,reachable_nodes=len(seen))
 def evaluate(self,outs,x):
  v=[0]*len(self.nodes)
  for i in sorted(self.reachable(outs)):
   t=self.nodes[i]
   if t[0]=='input':v[i]=x[t[1]]
   elif t[0]=='mul':v[i]=mul(v[t[1]],t[2])
   elif t[0]=='xor':v[i]=sumgf(v[j]for j in t[1:])
  return [v[i]for i in outs]
def build(method):
 d=DAG();x=list(range(1,17));conv=getattr(d,method)
 g=conv(x,A)[:16][::-1]
 y=conv(g,H)[:16][::-1]
 return d,y
if __name__=='__main__':
 results={}
 for method in['kconv','directconv','groupedconv']:
  d,y=build(method);results[method]=d.stats(y)
  print(method,results[method])
  for j in range(16):
   for b in range(8):
    x=[0]*16;x[j]=1<<b;assert d.evaluate(y,x)==lin(x)
  print('basis128ok')
 Path(__file__).with_name('counts.json').write_text(json.dumps(results,indent=2)+'\n')

