    var out: [16][4]W = undefined;
    for (0..16) |i| for (0..256) |v| {
        out[i][v / 64][v % 64] = mul(core.column_inverse[i], defs.pi_table[v]);
    };
    break :blk out;
};
inline fn firstSbox(a: W, comptime i: usize) W {
