        try testing.expectEqual(@as(W, @splat(mul(core.column_inverse[15 - i], defs.pi_inv_table[b]))), sbox(input, i, true, false));
        try testing.expectEqual(@as(W, @splat(defs.pi_inv_table[b])), sbox(input, i, true, true));
    };
