const std = @import("std");
const k = @import("src/kuznechik.zig");
const fact = @import("src/sliced_toeplitz.zig");
const broad = @import("src/sliced_toeplitz_broadcast.zig");
const enc = @import("src/encoded_toeplitz.zig");
const seed = @import("src/encoded_seeded.zig");
const enc_broadcast = @import("src/encoded_first_pool.zig");
const tf = @import("src/transitions.zig");
const f = @import("src/toeplitz_plain.zig");
const fs = @import("src/toeplitz_plain_broadcast.zig");
const poolcore = @import("src/toeplitz_core_pool.zig");
const original = @import("src/encoded_seeded_pool.zig");
const B = k.block;
const W = f.W;
const samples = 41;
const total_blocks = 4194304;
fn baseline(comptime inverse: bool, c: k.Cipher, messages: []align(16) B) void {
    if (inverse) c.decryptBlocks(messages) else c.encryptBlocks(messages);
}
fn candidate(comptime inverse: bool, comptime mode: u3, c: k.Cipher, messages: []align(16) B) void {
    if (mode == 6) {
        const ek = original.prepareKeys(if (inverse) &c.ik_inv else &c.ik, inverse);
        var rem = messages;
        while (rem.len >= 64) {
            if (inverse) original.decryptPrepared(&c.ik, &ek, rem[0..64]) else original.encryptPrepared(&ek, rem[0..64]);
            rem = rem[64..];
        }
    } else if (mode >= 3) {
        const module = if (mode == 3) enc else if (mode == 4) seed else enc_broadcast;
        const ek = module.prepareKeys(if (inverse) &c.ik_inv else &c.ik, inverse);
        var rem = messages;
        while (rem.len >= 64) {
            if (inverse) module.decryptPrepared(&c.ik, &ek, rem[0..64]) else if (mode == 5) module.encryptPrepared(&c.ik, &ek, rem[0..64]) else module.encryptPrepared(&ek, rem[0..64]);
            rem = rem[64..];
        }
    } else {
        const module = if (mode == 1) fact else broad;
        var rem = messages;
        while (rem.len >= 64) {
            if (inverse) module.decrypt(&c.ik, rem[0..64]) else module.encrypt(&c.ik, rem[0..64]);
            rem = rem[64..];
        }
    }
}
fn Wrapper(comptime inverse: bool, comptime mode: u3) type {
    return struct {
        fn run(c: k.Cipher, messages: []align(16) B) void {
            if (mode == 0) baseline(inverse, c, messages) else candidate(inverse, mode, c, messages);
        }
    };
}
const Outcome = struct { elapsed: u64, checksum: u64 };
noinline fn run(comptime func: anytype, comptime width: usize, c: k.Cipher, initial: *const [16384]B) !Outcome {
    var messages: [width]B align(16) = initial[0..width].*;
    for (0..16) |_| func(c, &messages);
    messages = initial[0..width].*;
    var timer = try std.time.Timer.start();
    for (0..total_blocks / width) |_| func(c, &messages);
    const elapsed = timer.read();
    std.mem.doNotOptimizeAway(&messages);
    var checksum: u64 = 0;
    for (messages) |b| {
        const words: [2]u64 = @bitCast(b);
        checksum +%= words[0] ^ words[1];
    }
    return .{ .elapsed = elapsed, .checksum = checksum };
}
fn compare(comptime inverse: bool, comptime width: usize, comptime mode: u3, c: k.Cipher, initial: *const [16384]B) !void {
    const base = Wrapper(inverse, 6).run;
    const cand = Wrapper(inverse, mode).run;
    var a: [samples]u64 = undefined;
    var b: [samples]u64 = undefined;
    var ratios: [samples]f64 = undefined;
    for (0..samples) |i| {
        var x: Outcome = undefined;
        var y: Outcome = undefined;
        if (i % 2 == 0) {
            x = try run(base, width, c, initial);
            y = try run(cand, width, c, initial);
        } else {
            y = try run(cand, width, c, initial);
            x = try run(base, width, c, initial);
        }
        if (x.checksum != y.checksum) return error.Mismatch;
        a[i] = x.elapsed;
        b[i] = y.elapsed;
        ratios[i] = @as(f64, @floatFromInt(b[i])) / @as(f64, @floatFromInt(a[i]));
    }
    var sa = a;
    var sb = b;
    var sr = ratios;
    std.mem.sort(u64, &sa, {}, std.sort.asc(u64));
    std.mem.sort(u64, &sb, {}, std.sort.asc(u64));
    std.mem.sort(f64, &sr, {}, std.sort.asc(f64));
    std.debug.print("{{\"direction\":\"{s}\",\"width\":{d},\"candidate\":\"{s}\",\"pairs\":{d},\"baseline_ns\":{d:.5},\"candidate_ns\":{d:.5},\"median_paired_ratio\":{d:.6},\"baseline_elapsed\":[", .{ if (inverse) "decrypt" else "encrypt", width, switch (mode) {
        1 => "plain105",
        2 => "plain105_qwordbroadcast",
        3 => "encoded75",
        4 => "encoded75_seeded",
        5 => "encoded75_first_Sbox",
        else => unreachable,
    }, samples, @as(f64, @floatFromInt(sa[samples / 2])) / total_blocks, @as(f64, @floatFromInt(sb[samples / 2])) / total_blocks, sr[samples / 2] });
    for (a, 0..) |v, i| std.debug.print("{s}{d}", .{ if (i == 0) "" else ",", v });
    std.debug.print("],\"candidate_elapsed\":[", .{});
    for (b, 0..) |v, i| std.debug.print("{s}{d}", .{ if (i == 0) "" else ",", v });
    std.debug.print("]}}\n", .{});
}
fn check() !void {
    try enc.selftest();
    try enc_broadcast.selftest();
    for (0..16) |position| for (0..256) |value| {
        var input: B = @splat(0);
        input[position] = @intCast(value);
        var columns: [16]W = undefined;
        for (0..16) |i| columns[i] = @splat(input[i]);
        const y = f.forward(W, columns);
        const z = f.inverse(W, columns);
        var scaled = columns;
        inline for (0..16) |i| scaled[i] = poolcore.multiplyConstant(scaled[i], poolcore.column_inverse[i]);
        var py = poolcore.forward(W, scaled);
        inline for (0..16) |i| py[i] = poolcore.multiplyConstant(py[i], poolcore.row_inverse[i]);
        const yy = fs.forward(W, columns);
        const zz = fs.inverse(W, columns);
        const expected = tf.l_trans(input);
        const expected_inv = tf.l_inv_trans(input);
        for (0..16) |i| {
            try std.testing.expectEqual(@as(W, @splat(expected[i])), y[i]);
            try std.testing.expectEqual(y[i], yy[i]);
            try std.testing.expectEqual(y[i], py[i]);
            try std.testing.expectEqual(@as(W, @splat(expected_inv[i])), z[i]);
            try std.testing.expectEqual(z[i], zz[i]);
        }
    };
    var prng = std.Random.DefaultPrng.init(0x666163746f726564);
    const random = prng.random();
    for (0..8) |_| {
        var key: k.key = undefined;
        random.bytes(std.mem.asBytes(&key));
        const c = k.Cipher.init(key);
        var input: [1024]B align(16) = undefined;
        random.bytes(std.mem.sliceAsBytes(&input));
        inline for (.{ false, true }) |inverse| {
            var a = input;
            baseline(inverse, c, &a);
            inline for (1..6) |mode| {
                var b = input;
                candidate(inverse, mode, c, &b);
                try std.testing.expectEqualSlices(B, &a, &b);
            }
        }
    }
    std.debug.print("CHECKS passed:4096 basis values/direction ×2 vector circuits;8 keys ×1024 arbitrary blocks/direction ×5 ciphers\n", .{});
}
pub fn main() !void {
    try check();
    var key: k.key = undefined;
    std.crypto.random.bytes(std.mem.asBytes(&key));
    const c = k.Cipher.init(key);
    var initial: [16384]B align(16) = undefined;
    std.crypto.random.bytes(std.mem.sliceAsBytes(&initial));
    inline for (.{ 64, 1024, 16384 }) |width| try compare(false, width, 5, c, &initial);
}

